{"file_text":"/**
 * Azure Service Principal Authentication with Client Secret
 * Complete TypeScript Example
 */

import { ClientSecretCredential } from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";
import { BlobServiceClient } from "@azure/storage-blob";

// ============================================================================
// 1. ENVIRONMENT CONFIGURATION
// ============================================================================

interface AzureServicePrincipalConfig {
  tenantId: string;
  clientId: string;
  clientSecret: string;
}

/**
 * Load configuration from environment variables
 * BEST PRACTICE: Never hardcode credentials in source code
 */
function loadConfigFromEnvironment(): AzureServicePrincipalConfig {
  const tenantId = process.env.AZURE_TENANT_ID;
  const clientId = process.env.AZURE_CLIENT_ID;
  const clientSecret = process.env.AZURE_CLIENT_SECRET;

  if (!tenantId || !clientId || !clientSecret) {
    throw new Error(
      "Missing required environment variables: AZURE_TENANT_ID, AZURE_CLIENT_ID, AZURE_CLIENT_SECRET"
    );
  }

  return { tenantId, clientId, clientSecret };
}

// ============================================================================
// 2. CREATE CLIENT SECRET CREDENTIAL
// ============================================================================

/**
 * Creates a ClientSecretCredential for authenticating to Azure services
 * 
 * @param config - Service Principal configuration
 * @returns ClientSecretCredential instance
 */
function createCredential(config: AzureServicePrincipalConfig): ClientSecretCredential {
  return new ClientSecretCredential(
    config.tenantId,
    config.clientId,
    config.clientSecret,
    {
      // Optional: Configure retry policy
      retryOptions: {
        maxRetries: 3,
        retryDelayInMs: 1000,
      },
      // Optional: Configure logging for debugging
      loggingOptions: {
        allowLoggingAccountIdentifiers: true,
      },
    }
  );
}

// ============================================================================
// 3. USING CREDENTIAL WITH AZURE SDK CLIENTS
// ============================================================================

/**
 * Example: Using credential with Azure Key Vault
 */
async function exampleKeyVault(credential: ClientSecretCredential): Promise<void> {
  const keyVaultUrl = process.env.KEY_VAULT_URL || "https://your-keyvault.vault.azure.net";

  const secretClient = new SecretClient(keyVaultUrl, credential);

  try {
    // Retrieve a secret
    const secret = await secretClient.getSecret("my-secret-name");
    console.log(`Retrieved secret: ${secret.name}`);
    // Use secret.value (but never log it!)
  } catch (error) {
    handleAuthenticationError(error, "Key Vault");
  }
}

/**
 * Example: Using credential with Azure Blob Storage
 */
async function exampleBlobStorage(credential: ClientSecretCredential): Promise<void> {
  const storageAccountName = process.env.STORAGE_ACCOUNT_NAME || "yourstorageaccount";
  const blobServiceUrl = `https://${storageAccountName}.blob.core.windows.net`;

  const blobServiceClient = new BlobServiceClient(blobServiceUrl, credential);

  try {
    // List containers
    const containers = blobServiceClient.listContainers();
    console.log("Storage containers:");
    for await (const container of containers) {
      console.log(`- ${container.name}`);
    }
  } catch (error) {
    handleAuthenticationError(error, "Blob Storage");
  }
}

/**
 * Example: Using credential with any Azure Resource Management client
 */
async function exampleGenericAzureService(credential: ClientSecretCredential): Promise<void> {
  // The credential can be used with any Azure SDK client that accepts TokenCredential
  // Examples:
  // - @azure/arm-resources (Resource Management)
  // - @azure/arm-compute (Virtual Machines)
  // - @azure/cosmos (Cosmos DB)
  // - @azure/communication-email (Communication Services)
  // - etc.

  // Example pattern:
  // const client = new SomeAzureClient(credential, subscriptionId);
  // const result = await client.someOperation();
}

// ============================================================================
// 4. ERROR HANDLING
// ============================================================================

/**
 * Handle authentication errors with detailed diagnostics
 */
function handleAuthenticationError(error: any, serviceName: string): void {
  console.error(`Authentication error when accessing ${serviceName}:`);

  if (error.statusCode === 401) {
    console.error("❌ Unauthorized (401): Invalid credentials or expired token");
    console.error("   Check that your Service Principal credentials are correct");
  } else if (error.statusCode === 403) {
    console.error("❌ Forbidden (403): Insufficient permissions");
    console.error("   Ensure your Service Principal has the required RBAC roles");
  } else if (error.code === "ENOTFOUND" || error.code === "ETIMEDOUT") {
    console.error("❌ Network error: Cannot reach Azure services");
    console.error("   Check your network connection and firewall settings");
  } else if (error.name === "CredentialUnavailableError") {
    console.error("❌ Credential unavailable");
    console.error("   Verify environment variables are set correctly");
  } else if (error.name === "AuthenticationError") {
    console.error("❌ Authentication failed");
    console.error(`   Details: ${error.message}`);
  } else {
    console.error("❌ Unexpected error:", error.message);
  }

  // Log error details for debugging (but never log secrets!)
  if (process.env.NODE_ENV === "development") {
    console.error("Error details:", {
      name: error.name,
      code: error.code,
      statusCode: error.statusCode,
      // Omit full error object to avoid leaking sensitive data
    });
  }

  throw error; // Re-throw to let caller handle it
}

/**
 * Validate credential before using it
 */
async function validateCredential(credential: ClientSecretCredential): Promise<boolean> {
  try {
    // Try to get a token for Azure Resource Manager
    const token = await credential.getToken("https://management.azure.com/.default");

    if (!token || !token.token) {
      console.error("❌ Failed to obtain access token");
      return false;
    }

    console.log("✅ Credential is valid");
    console.log(`   Token expires at: ${new Date(token.expiresOnTimestamp).toISOString()}`);
    return true;
  } catch (error) {
    console.error("❌ Credential validation failed");
    handleAuthenticationError(error, "Token Validation");
    return false;
  }
}

// ============================================================================
// 5. BEST PRACTICES FOR SECRET MANAGEMENT
// ============================================================================

/**
 * BEST PRACTICES:
 * 
 * 1. NEVER hardcode secrets in source code
 *    ❌ const clientSecret = "abc123...";
 *    ✅ const clientSecret = process.env.AZURE_CLIENT_SECRET;
 * 
 * 2. Use environment variables for local development
 *    - Store in .env file (add to .gitignore!)
 *    - Use dotenv package: require('dotenv').config()
 * 
 * 3. Use secure secret management in production:
 *    - Azure Key Vault for secrets storage
 *    - Managed Identity when possible (eliminates secrets entirely)
 *    - Azure App Configuration for non-sensitive config
 * 
 * 4. Rotate secrets regularly:
 *    - Set up automatic rotation policies
 *    - Monitor expiration dates
 *    - Use multiple client secrets for zero-downtime rotation
 * 
 * 5. Principle of least privilege:
 *    - Grant only necessary RBAC roles to Service Principal
 *    - Use separate Service Principals for different environments
 *    - Regularly audit permissions
 * 
 * 6. Never log secrets:
 *    - Sanitize logs to exclude credential information
 *    - Be careful with error messages and stack traces
 * 
 * 7. Use Managed Identity when possible:
 *    - Available in Azure App Service, Functions, VMs, AKS, etc.
 *    - No secrets to manage
 *    - Use DefaultAzureCredential for automatic fallback
 */

/**
 * Example: Using Azure Key Vault to store and retrieve secrets
 * This is a more secure approach than environment variables in production
 */
async function loadSecretsFromKeyVault(): Promise<AzureServicePrincipalConfig> {
  // Bootstrap credentials from environment (minimal set)
  const bootstrapConfig = loadConfigFromEnvironment();
  const credential = createCredential(bootstrapConfig);

  const keyVaultUrl = process.env.KEY_VAULT_URL || "https://your-keyvault.vault.azure.net";
  const secretClient = new SecretClient(keyVaultUrl, credential);

  try {
    // Retrieve secrets from Key Vault
    const tenantIdSecret = await secretClient.getSecret("azure-tenant-id");
    const clientIdSecret = await secretClient.getSecret("azure-client-id");
    const clientSecretSecret = await secretClient.getSecret("azure-client-secret");

    return {
      tenantId: tenantIdSecret.value!,
      clientId: clientIdSecret.value!,
      clientSecret: clientSecretSecret.value!,
    };
  } catch (error) {
    console.error("Failed to load secrets from Key Vault");
    throw error;
  }
}

// ============================================================================
// MAIN EXAMPLE
// ============================================================================

async function main(): Promise<void> {
  console.log("🔐 Azure Service Principal Authentication Example\n");

  try {
    // Load configuration from environment
    console.log("📋 Loading configuration...");
    const config = loadConfigFromEnvironment();
    console.log(`   Tenant ID: ${config.tenantId}`);
    console.log(`   Client ID: ${config.clientId}`);
    console.log(`   Client Secret: ${"*".repeat(8)}\n`);

    // Create credential
    console.log("🔑 Creating ClientSecretCredential...");
    const credential = createCredential(config);
    console.log("   ✅ Credential created\n");

    // Validate credential
    console.log("✔️  Validating credential...");
    const isValid = await validateCredential(credential);
    if (!isValid) {
      throw new Error("Credential validation failed");
    }
    console.log();

    // Use credential with Azure services
    console.log("☁️  Using credential with Azure services...\n");

    console.log("1️⃣  Key Vault example:");
    await exampleKeyVault(credential);
    console.log();

    console.log("2️⃣  Blob Storage example:");
    await exampleBlobStorage(credential);
    console.log();

    console.log("✅ All operations completed successfully!");

  } catch (error: any) {
    console.error("\n❌ Application failed:", error.message);
    process.exit(1);
  }
}

// ============================================================================
// ALTERNATIVE: Using DefaultAzureCredential (Recommended for Production)
// ============================================================================

/**
 * For production applications, consider using DefaultAzureCredential
 * which automatically tries multiple authentication methods in order:
 * 1. Environment variables (Service Principal)
 * 2. Managed Identity
 * 3. Azure CLI
 * 4. Azure PowerShell
 * etc.
 * 
 * This provides flexibility without code changes across environments.
 */
import { DefaultAzureCredential } from "@azure/identity";

function createFlexibleCredential(): DefaultAzureCredential {
  return new DefaultAzureCredential({
    // Will use Service Principal from environment variables if available
    // Falls back to Managed Identity in Azure environments
    // Falls back to Azure CLI during local development
  });
}

// Run main function if this file is executed directly
if (require.main === module) {
  main().catch(console.error);
}

export {
  createCredential,
  validateCredential,
  loadConfigFromEnvironment,
  handleAuthenticationError,
  createFlexibleCredential,
};
